read_items.source:
async function run(input, tools) {
  const repo = String((input.settings || {}).github_repo || "").trim().replace(/^https?:\/\/(?:www\.)?github\.com\//i, "").replace(/\.git$/i, "").replace(/\/+$/, "").split("/").slice(0, 2).join("/");
  if (!repo) return { items: [] };
  const got = await tools.github.read({ op: "commits", repo: repo });
  const list = got && Array.isArray(got.items) ? got.items : [];
  const items = list.map(function (x) {
    return { id: String(x.sha || x.number || ""), title: String(x.message || x.title || ""), author: String(x.author || ""), date: String(x.date || x.created_at || ""), url: String(x.url || "") };
  });
  return { items: items };
}

judge_items.source:
async function run(input, tools) {
  const repo = String((input.settings || {}).github_repo || "").trim().replace(/^https?:\/\/(?:www\.)?github\.com\//i, "").replace(/\.git$/i, "").replace(/\/+$/, "").split("/").slice(0, 2).join("/");
  const items = (Array.isArray(input.items) ? input.items : []).slice().reverse();
  const results = [];
  for (const item of items) {
    let changed = [];
    try {
      const got = await tools.github.read({ op: "commit", repo: repo, sha: item.id });
      changed = got && Array.isArray(got.items) ? got.items : [];
    } catch (e) {
      changed = [];
    }
    const judged = await tools.serv.reason({
      task: "Judge the quality of this commit's changes: name each real problem (a bug, a risky or unclear change, a missing test where it matters) in a few words, or none, and give a one-line verdict.",
      data: { item: { title: item.title, author: item.author, date: item.date }, changes: changed.map(function (f) { return { name: f.filename, status: f.status, added: f.additions, removed: f.deletions, patch: f.patch }; }) },
      answer: { verdict: "text", problems: "list" },
    });
    const problems = Array.isArray(judged.problems) ? judged.problems.map(String).filter(function (p) { return p.trim(); }) : [];
    results.push({ id: item.id, title: item.title, url: item.url, verdict: String(judged.verdict || ""), problems: problems });
  }
  return { results: results };
}

write_message.source:
async function run(input) {
  const results = Array.isArray(input.results) ? input.results : [];
  if (!results.length) return { message: null };
  const where = String((input.settings || {}).github_repo || "").trim();
  const flagged = results.filter(function (r) { return (r.problems || []).length; }).length;
  const head = where + ": " + results.length + " " + (results.length === 1 ? "commit" : "commits") + " checked, " + (flagged ? flagged + " with problems." : "nothing wrong found.");
  const lines = results.map(function (r) {
    const name = String(r.id).slice(0, 7);
    const problems = (r.problems || []).slice(0, 5).map(function (p) { return "\n  - " + p; }).join("");
    return name + " " + r.title + ": " + r.verdict + problems;
  });
  return { message: { text: [head].concat(lines).join("\n").slice(0, 3500) } };
}
